import{c as e,Q as a,j as l,m as r}from"./chunks/framework.DOi4mjdC.js";const o="/assets/AI-Core%E5%86%85%E9%83%A8%E5%B9%B6%E8%A1%8C%E8%AE%A1%E7%AE%97%E6%9E%B6%E6%9E%84%E6%8A%BD%E8%B1%A1.BNwzTNKg.png",E="/assets/%E5%9B%BE1-AI-Core%E5%86%85%E9%83%A8%E5%B9%B6%E8%A1%8C%E8%AE%A1%E7%AE%97%E6%9E%B6%E6%9E%84%E6%8A%BD%E8%B1%A1%E7%A4%BA%E6%84%8F%E5%9B%BE.CnKcJPNe.png",i="/assets/Iterate_flase.D97I7aRV.png",s="/assets/%E5%9B%BE1-AI-Core%E5%86%85%E9%83%A8%E5%B9%B6%E8%A1%8C%E8%AE%A1%E7%AE%97%E6%9E%B6%E6%9E%84%E6%8A%BD%E8%B1%A1%E7%A4%BA%E6%84%8F%E5%9B%BE-43.BP_Laf6C.png",u=JSON.parse('{"title":"同步控制简介","description":"","frontmatter":{},"headers":[{"level":1,"title":"同步控制简介","slug":"同步控制简介"},{"level":2,"title":"同步控制简介","slug":"同步控制简介"},{"level":2,"title":"硬件流水类型","slug":"硬件流水类型"},{"level":2,"title":"同步控制分类","slug":"同步控制分类"},{"level":2,"title":"什么时候需要开发者手动插入同步","slug":"什么时候需要开发者手动插入同步"}],"relativePath":"api/SIMD-API/基础API/同步控制/核内同步/同步控制简介.md","filePath":"api/SIMD-API/基础API/同步控制/核内同步/同步控制简介.md"}'),p={name:"api/SIMD-API/基础API/同步控制/核内同步/同步控制简介.md"};function A(c,t,d,n,h,B){return a(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="同步控制简介" tabindex="-1">同步控制简介 <a class="header-anchor" href="#同步控制简介" aria-label="Permalink to &quot;同步控制简介&quot;">​</a></h1><p>开发者可以使用同步控制接口来自行完成同步控制。需要注意的是，通常情况下，开发者基于TPipe编程范式进行编程时不需要关注同步，编程模型帮助开发者完成了同步控制；使用编程模型和范式是我们推荐的编程方式，自行同步控制可能会带来一定的编程复杂度，不建议开发者使用。<a href="./TQueSync/TQueSync.html">TQueSync</a>类接口和<a href="./SetFlag-WaitFlag(ISASI).html">SetFlag/WaitFlag(ISASI)</a>中提供的同步控制接口的区别在于，<a href="./SetFlag-WaitFlag(ISASI).html">SetFlag/WaitFlag(ISASI)</a>中的接口标注为ISASI类别，不能保证跨硬件版本兼容；TQueSync类接口可以保证跨硬件版本兼容。</p><h2 id="同步控制简介-1" tabindex="-1">同步控制简介 <a class="header-anchor" href="#同步控制简介-1" aria-label="Permalink to &quot;同步控制简介&quot;">​</a></h2><p>介绍同步控制之前需要先回顾一下<a href="#fig758422819442">图1</a>。</p><p>AI Core内部的异步并行计算过程：Scalar计算单元读取指令序列，并把向量计算、矩阵计算、数据搬运指令发射给对应单元的指令队列，向量计算单元、矩阵计算单元、数据搬运单元异步的并行执行接收到的指令。该过程可以参考<a href="#fig758422819442">图1</a>中蓝色箭头所示的指令流。</p><p>不同的指令间有可能存在依赖关系，为了保证不同指令队列间的指令按照正确的逻辑关系执行，Scalar计算单元也会给对应单元下发同步指令。各单元之间的同步过程可以参考<a href="#fig758422819442">图1</a>中的绿色箭头所示的同步信号流。</p><p>AI Core内部数据处理的基本过程：DMA搬入单元把数据搬运到Local Memory，Vector/Cube计算单元完成数据计算，并把计算结果写回Local Memory，DMA搬出单元把处理好的数据搬运回Global Memory。该过程可以参考<a href="#fig758422819442">图1</a>中的红色箭头所示的数据流。</p><p><strong>图 1</strong> AI Core内部并行计算架构抽象<br><img src="'+o+'" alt="" title="AI-Core内部并行计算架构抽象"></p><p>从上图可以了解到AI Core内部的执行单元是异步并行的，在读写Local Memory内存时，可能存在依赖，需要进行同步控制。</p><p>下图示例描述了一个常见的Vector计算数据流：</p><ol><li>先通过DMA执行单元将数据从Global Memory搬入到Local Memory；</li><li>进行计算；</li><li>然后再通过DMA执行单元将计算结果从Local Memory搬出到Global Memory。</li></ol><p><img src="'+E+'" alt=""></p><p>四个执行单元Scalar、Vector、DMA(VECIN)、DMA(VECOUT)并行执行，若访问同一片Local Memory，需要同步机制来控制他们的访问时序：保证先搬入Local Memory后再计算，计算完成后再搬出。</p><p><img src="'+i+'" alt=""></p><h2 id="硬件流水类型" tabindex="-1">硬件流水类型 <a class="header-anchor" href="#硬件流水类型" aria-label="Permalink to &quot;硬件流水类型&quot;">​</a></h2><p>AI Core内部并行的指令流水类型和解释如下所示：</p><div class="note custom-block github-alert"><p class="custom-block-title">说明</p><p>不同的硬件架构，每一种硬件流水类型包含的具体流水会有所差异，详细介绍请参考<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/guide/%E7%BC%96%E7%A8%8B%E6%8C%87%E5%8D%97/%E9%AB%98%E7%BA%A7%E7%BC%96%E7%A8%8B/%E7%A1%AC%E4%BB%B6%E5%AE%9E%E7%8E%B0/%E7%A1%AC%E4%BB%B6%E5%AE%9E%E7%8E%B0.md" target="_blank" rel="noreferrer">硬件实现</a>章节。</p></div><p><strong>表 1</strong> 指令流水类型和相关说明</p><table tabindex="0"><thead><tr><th>流水类型</th><th>含义</th></tr></thead><tbody><tr><td>PIPE_S</td><td>标量流水线，使用Tensor GetValue函数时为此流水</td></tr><tr><td>PIPE_V</td><td>矢量计算流水及部分硬件架构下的L0C Buffer-&gt;UB数据搬运流水</td></tr><tr><td>PIPE_M</td><td>矩阵计算流水</td></tr><tr><td>PIPE_MTE1</td><td>L1 Buffer -&gt;L0A Buffer、L1 Buffer-&gt;L0B Buffer数据搬运流水</td></tr><tr><td>PIPE_MTE2</td><td>GM-&gt;L1 Buffer、GM-&gt;UB等数据搬运流水</td></tr><tr><td>PIPE_MTE3</td><td>UB-&gt;GM等数据搬运流水</td></tr><tr><td>PIPE_FIX</td><td>L0C Buffer-&gt;GM、L0C Buffer -&gt;L1等数据搬运流水</td></tr></tbody></table><h2 id="同步控制分类" tabindex="-1">同步控制分类 <a class="header-anchor" href="#同步控制分类" aria-label="Permalink to &quot;同步控制分类&quot;">​</a></h2><p>对上述并行流水的同步控制分为两种：</p><ul><li><p>多流水同步：通过<a href="./TQueSync/TQueSync.html">TQueSync</a>的SetFlag/WaitFlag或者<a href="./SetFlag-WaitFlag(ISASI).html">SetFlag/WaitFlag(ISASI)</a>接口进行不同流水线间的同步控制。</p><ul><li>SetFlag：当前序指令的所有读写操作都完成之后，当前指令开始执行，并将硬件中的对应标志位设置为1。</li><li>WaitFlag：当执行到该指令时，如果发现对应标志位为0，该队列的后续指令将一直被阻塞；如果发现对应标志位为1，则将对应标志位设置为0，同时后续指令开始执行。</li></ul></li><li><p>单流水同步：通过<a href="./PipeBarrier(ISASI).html">PipeBarrier(ISASI)</a>完成同一流水线内的同步控制，用于在同一流水线内部约束执行顺序。其作用是，保证前序指令中所有数据的读写工作全部完成，后序指令才能执行。</p></li></ul><h2 id="什么时候需要开发者手动插入同步" tabindex="-1">什么时候需要开发者手动插入同步 <a class="header-anchor" href="#什么时候需要开发者手动插入同步" aria-label="Permalink to &quot;什么时候需要开发者手动插入同步&quot;">​</a></h2><ul><li><p>Vector计算单元</p><ul><li><p>单流水同步：PIPE_V由编译器自动完成同步插入，PIPE_MTE2/PIPE_MTE3在搬运地址有重叠的情况下需要开发者插入同步（具体示例请参考<a href="./../../Memory数据搬运/DataCopy/基础数据搬运.html#li71531626153617">注意事项</a>）。</p></li><li><p>多流水同步：PIPE_V、PIPE_MTE2、PIPE_MTE3、PIPE_S之间的多流水同步，都是双向的，如下图所示，黄色线条表示的同步由编译器自动完成同步插入，剩余的同步由Ascend C框架完成。例外情况：使用涉及标量计算的原子操作接口（如<a href="./../../原子操作/AtomicAdd.html">AtomicAdd</a>）时，如果标量计算单元和搬运单元（MTE2/MTE3）在读写GM时存在数据依赖，开发者需要根据实际情况插入同步。详细内容参见具体的API说明。</p><p><img src="'+s+'" alt=""></p></li></ul></li><li><p>Cube计算单元</p><p>Cube侧所有流水同步都由Ascend C框架完成，不需要算子开发者插入同步。</p><div class="note custom-block github-alert"><p class="custom-block-title">说明</p><p>上文描述的编译器自动完成同步插入强依赖于LocalTensor间依赖关系，部分场景下需要开发者手动完成同步，具体的约束说明请参考。</p></div></li></ul>',24)])])}const g=e(p,[["render",A]]);export{u as __pageData,g as default};
